import requests,io,numpy as np,collections
from PIL import Image
lat,lon=35.4308,-99.3943;dx=.32;dy=.25; box=[lon-dx,lat-dy,lon+dx,lat+dy]
p={'service':'WMS','version':'1.1.1','request':'GetMap','layers':'nexrad-n0q-wmst','styles':'','srs':'EPSG:4326','bbox':','.join(map(str,box)),'width':128,'height':100,'format':'image/png','transparent':'true','time':'2022-05-11T05:35:00Z'}
im=Image.open(io.BytesIO(requests.get('https://mesonet.agron.iastate.edu/cgi-bin/wms/nexrad/n0q-t.cgi',params=p,timeout=50).content));src=Image.open(io.BytesIO(requests.get('https://mesonet.agron.iastate.edu/archive/data/2022/05/11/GIS/uscomp/n0q_202205110535.png',timeout=65).content));pal=np.array(src.getpalette()).reshape(256,3);rgb=np.asarray(im)[:,:,:3]; vals=np.unique(rgb.reshape(-1,3),axis=0);unknown=[tuple(x) for x in vals if not np.any(np.all(pal==x,axis=1))]; print('unique',len(vals),'unknown',len(unknown),unknown[:12]);
ys,xs=np.indices(rgb.shape[:2]);lons=box[0]+(xs+.5)*(box[2]-box[0])/128;lats=box[3]-(ys+.5)*(box[3]-box[1])/100;source=np.asarray(src);jj=np.clip(np.rint((50-lats)/.005).astype(int),0,source.shape[0]-1);ii=np.clip(np.rint((lons+126)/.005).astype(int),0,source.shape[1]-1); expected=pal[source[jj,ii]];print('equal_fraction',np.mean(np.all(rgb==expected,axis=2)));lut={tuple(c):i for i,c in enumerate(pal)}; mapped=np.array([lut[tuple(c)] for c in rgb.reshape(-1,3)]).reshape(rgb.shape[:2]);print('threshold_agree',np.mean((mapped>=145)==(source[jj,ii]>=145)),'wmsidx',mapped[50,64],'sourceidx',source[jj[50,64],ii[50,64]]);
